def _get(name: str) -> List[float]:
    for n, v in EXPECTED:
        if n == name:
            return v
    raise ValueError("missing " + name)

def check(name: str, got, rtol: float = 1e-7, atol: float = 1e-10):
    want = _get(name)
    g = List[float]()
    for v in got:
        if isinstance(v, np.ndarray):
            for w in v.ravel():
                g.append(float(w))
        else:
            g.append(float(v))
    ok = len(g) == len(want)
    if ok:
        for i in range(len(want)):
            if abs(g[i] - want[i]) > atol + rtol * abs(want[i]):
                ok = False
    if not ok:
        print("TEST FAILED:", name, g, want)

rng = np.random.RandomState(0)
X = rng.randn(60, 3)
eta = 0.3 * X[:, 0] - 0.5 * X[:, 1] + 0.2
yp = rng.poisson(np.exp(eta)).astype(float)
yg = rng.gamma(2.0, np.exp(eta) / 2.0)
yr = X @ np.array([1.0, -2.0, 0.5]) + 0.3 * rng.randn(60)
yo = yr.copy()
yo[:6] += 8.0
sw = rng.uniform(0.5, 2.0, 60)
XW = rng.randn(8, 12)
yw = XW[:, 0] - XW[:, 3] + 0.1 * rng.randn(8)

def cat(*parts) -> List[float]:
    r = List[float]()
    for p in parts:
        if isinstance(p, np.ndarray):
            for v in p.ravel():
                r.append(float(v))
        elif isinstance(p, List[float]):
            for v in p:
                r.append(v)
        else:
            r.append(float(p))
    return r

def g(name: str, m):
    check(name, cat(m.coef_, m.intercept_, m.n_iter_), 1e-8, 1e-11)

